update books set first_publish_year = 1979, page_count = 216, description = 'The Hitchhiker''s Guide to the Galaxy is the first of six books in the Hitchhiker''s Guide to the Galaxy comedy science fiction "hexalogy" by Douglas Adams. The novel is an adaptation of the first four parts of Adams''s radio series of the same name. The novel was first published in London on 12 October 1979.' where id = 'bk6';
update books set first_publish_year = 1937, page_count = 310, description = 'The Hobbit is a tale of high adventure, undertaken by a company of dwarves in search of dragon-guarded gold. A reluctant partner in this perilous quest is Bilbo Baggins, a comfort-loving unambitious hobbit, who surprises even himself by his resourcefulness and skill as a burglar.

Encounters with trolls, goblins, dwarves, elves, and giant spiders, conversations with the dragon, Smaug, and a rather unwilling presence at the Battle of Five Armies are just some of the adventures that befall Bilbo.' where id = 'bkx5fsr2q';
update books set first_publish_year = 1969, page_count = 304, description = 'The Left Hand of Darkness by Ursula K Le Guin (1969). The thought experiment is quickly revealed: "The king was pregnant," the book tells us early on, and after that we learn more and more about this planet named Winter, stuck in an ice age, where the humans are most of the time neither male nor female, but with the potential to become either.' where id = 'bk1';
