update books set first_publish_year = 2006, page_count = 256, description = 'Cormac McCarthy''s tenth novel, The Road, is his most harrowing yet deeply personal work. Some unnamed catastrophe has scourged the world to a burnt-out cinder, inhabited by the last remnants of mankind and a very few surviving dogs and fungi. Through this nightmarish residue of America a haggard father and his young son attempt to flee the oncoming Appalachian winter and head towards the southern coast along carefully chosen back roads.

The Road was the winner of the 2006 Pulitzer Prize for Literature.' where id = 'bkm8rmcvh';
update books set first_publish_year = 1988, page_count = 187, description = 'Touching the Void is a 1988 book by Joe Simpson, recounting his and Simon Yates''s disastrous and nearly fatal climb of the 6,344-metre (20,813 foot) Siula Grande in the Peruvian Andes in 1985.' where id = 'bk8';
update books set first_publish_year = 2004, page_count = 450, description = '"True North is the story of a family torn apart and a man engaged in profound reckoning with the damage scarred into the American soil. The scion of a family of wealthy timber barons, David Burkett has grown up with a father who is a malevolent force more than a father, and a mother made vague and numb by alcohol and pills."' where id = 'bk0qvapxi';
update books set first_publish_year = 1936, page_count = 222, description = 'A lyrical account of the author’s time as a pilot flying the dangerous mail routes across the Sahara and the Andes. Many incidents are recounted, including the time he crashed his plane in the Sahara and, along with his navigator, is forced to walk for days without food or water before finding safety.' where id = 'bk14';
